"use client";
import React, { useEffect, useState } from "react";
import { FcGoogle } from "react-icons/fc";
import { IoEyeOutline } from "react-icons/io5";
import { useRouter } from "next/navigation";
import "../globals.css";
const AuthPage = () => {
  const [isLogin, setIsLogin] = useState<boolean>(true);
  const [isClient, setIsClient] = useState(false); // Đảm bảo đồng bộ hóa CSR
  const router = useRouter();

  useEffect(() => {
    setIsClient(true); // Chỉ render nội dung sau khi client tải xong
  }, []);

  if (!isClient) return null; // Tránh render trên server

  const toggleAuthMode = () => {
    setIsLogin(!isLogin);
    router.push(isLogin ? "/signup" : "/login");
  };

  return (
    <div className="h-screen flex flex-col items-center justify-center bg-gradient-to-r from-green-100 via-purple-100 to-purple-200">
      {/* Header */}
      <div className="absolute top-0 left-0 w-full flex justify-between items-center px-8 py-4">
        <div className="text-2xl font-bold">Gradient</div>
        <div className="flex space-x-2">
          <button
            className={`px-4 py-2 rounded-l-full ${
              isLogin ? "bg-gray-800 text-white" : "bg-gray-200"
            }`}
            onClick={() => router.push("/login")}
          >
            Log In
          </button>
          <button
            className={`px-4 py-2 rounded-r-full ${
              !isLogin ? "bg-gray-800 text-white" : "bg-gray-200"
            }`}
            onClick={() => router.push("/signup")}
          >
            Sign Up
          </button>
        </div>
      </div>

      {/* Form */}
      <div className="w-full max-w-md bg-white rounded-2xl shadow-lg p-8">
        <h2 className="text-xl font-medium text-center">
          {isLogin ? "Log In" : "Sign Up"}
        </h2>
        <p className="text-center text-gray-500 mt-2">
          {isLogin
            ? "Welcome back! Log in to stay updated with all your nodes and rewards."
            : "Start your journey on Gradient Network and shape the future of compute."}
        </p>
        <form className="space-y-4 mt-6">
          {/* Email */}
          <div>
            <label className="block text-sm font-medium text-gray-800 ">
              Email
            </label>
            <input
              type="email"
              placeholder="Enter Email"
              className="mt-1 block w-full px-5 py-2 border border-gray-300 rounded-full shadow-sm hover:border-[#1677ff] focus:border-[#1677ff] focus:ring-1 focus:ring-[#1677ff] focus:outline-none text-sm"
            />
          </div>

          {/* Password */}
          <div>
            <label className="block text-sm font-medium text-gray-8800">
              Password
            </label>
            <div className="relative">
              <input
                type="password"
                placeholder="Enter Password"
                className="mt-1 block w-full px-5 text-sm py-2 border border-gray-300 rounded-full shadow-sm hover:border-[#1677ff] focus:border-[#1677ff] focus:ring-1 focus:ring-[#1677ff] focus:outline-none"
              />
              <span className="absolute inset-y-0 right-0 flex items-center pr-3 cursor-pointer text-gray-500">
                <IoEyeOutline />
              </span>
            </div>
          </div>

          {/* Forgot Password */}
          <div className="  text-right text-xs text-gray-500 underline ">
            <a href="#">Forgot Password</a>
          </div>

          {/* Buttons */}
          {/* Nút */}
          <button
            type="button"
            className="relative w-full flex items-center justify-center bg-gradient-to-r from-gray-800 via-gray-700 to-gray-800 text-white py-2 px-4 rounded-full hover:bg-gradient-to-r hover:from-gray-900 hover:via-gray-500 hover:to-gray-900 custom-flying-button"
          >
            {isLogin ? "Đăng nhập" : "Đăng ký"}
            <div className="absolute top-0 left-0 w-full h-full pointer-events-none">
              {/* Hạt di chuyển bên trong nút */}
              {[...Array(10)].map((_, index) => (
                <div
                  key={index}
                  className="particle"
                  style={{
                    top: `${Math.random() * 100}%`, // Vị trí ngẫu nhiên dọc theo chiều cao
                    left: `${Math.random() * 100}%`, // Vị trí ngẫu nhiên ngang
                    animationDelay: `${Math.random() * 1}s`, // Thời gian trễ ngẫu nhiên cho từng hạt
                  }}
                ></div>
              ))}
            </div>
            <canvas className="w-full h-full absolute inset-0 pointer-events-none"></canvas>
          </button>

          {/* Google Sign In */}
          <button
            type="button"
            className="w-full border border-gray-300 text-black py-2 px-4 rounded-full flex items-center justify-center space-x-2 group-hover hover:text-[#1677ff] hover:border-[#1677ff] "
          >
            <FcGoogle />
            <span>Sign in with Google</span>
          </button>
        </form>

        {/* Switch between Log In and Sign Up */}
        <p className="mt-6 text-center text-sm text-gray-500">
          {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
          <button
            type="button"
            className="text-blue-500 hover:underline"
            onClick={toggleAuthMode}
          >
            {isLogin ? "Sign Up" : "Log In"}
          </button>
        </p>
      </div>
    </div>
  );
};

export default AuthPage;
